using System;
using System.IO;
using System.Collections.Generic;
using System.Reflection;
using System.Windows.Forms;
namespace Downfield {
public static class PlaybookUpdateTests {
 static int checks,failures;static void Check(bool value,string message){checks++;if(!value){failures++;Console.WriteLine("FAIL Playbook update: "+message);}}
 static Simulation Match(Franchise f){Simulation s=new Simulation(120);s.Practice=true;f.Apply(s,(f.UserTeam+1)%12);s.NewGame();return s;}
 public static int Run(){checks=failures=0;string old=Profile.StorageOverride,folder=Path.Combine(Path.GetTempPath(),"Downfield-playbook-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{
  Franchise f=Franchise.Create(new Profile(),new Roster());Simulation s=Match(f);DrawnPlay p=DrawnPlay.Default(14,s);p.Routes[0]=DrawnPlay.Preset(0,"CURL",-19,0);Check(f.SaveCustomPlay(p,"FOOL THEM"),"save named custom call");int id=p.LibraryId;p.Routes[0].Points[0].X=9;Check(f.PlayLibrary[0].Routes[0].Points[0].X==-19,"saved routes are independent copies");DrawnPlay second=DrawnPlay.Default(0,s);Check(f.SaveCustomPlay(second,"GOOF BALL"),"second call is added rather than replacing first");f=Franchise.Load(new Profile(),new Roster());Check(f.PlayLibrary.Count==2&&f.PlayLibrary[0].Name=="FOOL THEM","multiple named calls survive restart");s=Match(f);s.CallPlay(s.PlayNames.Length);Check(s.UseCustom&&s.CustomPlay.LibraryId==id&&!s.RunPlay,"saved call selected from combined playbook");s.CustomPlay.Name="UPDATED";Check(f.SaveCustomPlay(s.CustomPlay,"UPDATED")&&f.PlayLibrary.Count==2,"editing a saved play updates its own slot");s.CallPlay(0);Check(!s.UseCustom,"stock call clears custom routes");f.DeleteCustomPlay(id);Check(f.PlayLibrary.Count==1,"delete removes only chosen play");
  foreach(int play in new int[]{0,1,2,3,4,5,14,15,16,17,18,19,30,34,37,40,41}){s=Match(f);s.CallPlay(play);List<RouteNode> preview=s.PreviewRoute(play,0);Player receiver=s.Receiver(0);s.Snap();for(int frame=0;frame<40;frame++)s.Update(.05f,0,0);RouteNode mark=preview[10];Check(Simulation.Distance(mark.X,mark.Z+s.Spot,receiver.X,receiver.Z)<3.2f,"preview follows the actual receiver at two seconds / "+play);}
  f=Franchise.Create(new Profile(),new Roster());foreach(ClubPlayer qb in f.Squad(f.UserTeam))if(qb.Role=="QB")qb.InjuryWeeks=4;s=Match(f);Check(s.EmergencyChoicePending,"QB shortage requests a choice");s.Snap();Check(s.State==Phase.PreSnap,"cannot snap before emergency QB selection");ClubPlayer injured=f.Squad(f.UserTeam).Find(q=>q.Role=="QB");Check(!s.ChooseEmergencyQB(injured.Id),"cannot put injured QB back in");foreach(string role in new string[]{"WR","OL","CB","RB"}){s.EmergencyChoicePending=true;ClubPlayer choice=f.Squad(f.UserTeam).Find(q=>q.Role==role&&q.InjuryWeeks==0);Check(s.ChooseEmergencyQB(choice.Id)&&s.Controlled.ClubId==choice.Id&&s.Controlled.Number==choice.Number,"choose actual healthy "+role+" at QB");HashSet<int> ids=new HashSet<int>();bool unique=true;foreach(Player actor in s.Players)if(actor.Team==0&&actor.Active)unique&=ids.Add(actor.ClubId);Check(unique&&s.ThrowAbility<.6f,"no duplicate identity and low throwing ability / "+role);s.Snap();Check(s.CanThrow,"emergency "+role+" may pass behind line");s.BeginPass(DefenseBalanceTests.OpenReceiver(s));s.Charge=.3f;s.ReleasePass();Check(s.State==Phase.Flight,"emergency "+role+" launches real pass");s=Match(f);}
  Check(f.EmergencyQB>0&&!s.EmergencyChoicePending,"chosen emergency backup remembered");
  f=Franchise.Create(new Profile(),new Roster());for(int play=24;play<48;play++){s=Match(f);s.CallPlay(play);s.Snap();bool finite=true;for(int n=0;n<200;n++){s.Update(.02f,0,0);foreach(Player actor in s.Players)finite&=!float.IsNaN(actor.X)&&!float.IsNaN(actor.Z);}Check(finite,"trick call runs safely / "+s.PlayNames[play]);}
  s=Match(f);int rb=f.Starter(f.UserTeam,1).Id;s.CallPlay(30);Check(s.Controlled.ClubId==rb&&s.Players[1].Active,"wildcat puts real RB at QB and dresses actual second back");s.Snap();Check(s.CanThrow&&s.TrickPasser&&s.ThrowAbility<1,"wildcat pass is a real lower-skill passing play");s=Match(f);s.CallPlay(29);s.CallPlay(0);Check(s.Controlled.ClubId==f.Starter(f.UserTeam,0).Id&&!s.Wildcat,"leaving wildcat restores actual quarterback");s=Match(f);s.CallPlay(25);s.Snap();for(int n=0;n<40;n++)s.Update(.02f,0,0);Check(s.Controlled.Role=="RB"&&s.CanThrow,"HB pass unlocks ball carrier after backward give");s=Match(f);s.CallPlay(24);s.Snap();for(int n=0;n<150;n++)s.Update(.02f,0,0);Check(s.Controlled.Role=="QB"&&s.CanThrow,"automatic flea flicker returns the ball to QB");
  s=Match(f);s.CallPlay(24);s.Snap();for(int n=0;n<150;n++)s.Update(.02f,0,0);Check(s.Playbook==24&&!s.RunPlay,"flea-flicker return preserves its advertised receiver routes");int specialPassers=0,specialCatches=0;for(int seed=0;seed<24;seed++){s=new Simulation(88000+seed);s.Practice=true;s.NewGame();s.CallPlay(32);s.Snap();for(int n=0;n<180;n++)s.Update(.02f,0,0);if(s.Controlled==s.Players[10]&&s.CanThrow){specialPassers++;s.BeginPass(4);s.Charge=.35f;s.ReleasePass();for(int n=0;n<150&&s.State==Phase.Flight;n++)s.Update(.02f,0,0);if(s.Completions>0&&s.Controlled==s.Players[0])specialCatches++;}}Console.WriteLine("Philly Special: WR passers "+specialPassers+" / QB catches "+specialCatches+" of 24");Check(specialPassers>=18,"Philly Special completes real RB-to-WR backward exchange");Check(specialCatches>=10,"quarterback can catch a real forward Philly Special pass without meter assist");
  ControlBindings keys=new ControlBindings();keys.BindKey(0,Keys.I);keys.BindKey(11,Keys.G);keys.BindKey(22,Keys.H);keys.BindPad(Input.Y,Input.X);keys.SwapSticks=true;keys.Save();ControlBindings loaded=ControlBindings.Load();Check(loaded.Key(0)==Keys.I&&loaded.Key(11)==Keys.G&&loaded.Key(22)==Keys.H&&loaded.SwapSticks,"keyboard and stick assignments persist independently of franchise");Check(loaded.TranslatePad(Input.X)==Input.Y&&loaded.TranslatePad(Input.Y)==Input.X,"controller conflicts swap and raw buttons translate");loaded.BindKey(1,Keys.I);Check(loaded.Key(1)==Keys.I&&loaded.Key(0)==Keys.S,"keyboard move conflict swaps");Check(loaded.BindKey(0,Keys.Escape).Contains("RESERVED"),"escape remains available for menu recovery");Input input=new Input();input.Bindings=keys;input.SuppressPad=true;input.Context="qb";input.KeysDown.Add(Keys.I);input.KeysDown.Add(Keys.G);input.Poll();Check(input.MoveZ==1&&input.Pressed(Input.A),"remapped keyboard movement and pass reach live input");input.KeysDown.Clear();input.Poll();Check(input.Released(Input.A),"remapped pass release is detected");input.KeysDown.Add(Keys.H);input.Context="flight";input.Poll();Check(input.CatchPressed,"aggressive catch uses its keyboard binding");
  f=Franchise.Create(new Profile(),new Roster());f.Credits=500;ClubPlayer give=f.Starter(f.UserTeam,0),get=f.Starter(1,1);give.OVR=95;give.Potential=95;give.Age=24;give.Years=3;get.OVR=82;get.Potential=85;get.Age=29;get.Years=2;Check(f.Trade(give.Id,get.Id)&&get.Team==f.UserTeam&&give.Team==1,"QB can be traded for RB");bool slots=true;foreach(ClubPlayer actor in f.Players)if(actor.Slot>=0)slots&=Franchise.Roles[actor.Slot]==actor.Role;Check(slots,"cross-position trade never assigns a player to wrong role");ClubPlayer bad=f.Squad(f.UserTeam).Find(q=>q.Role=="OL"),star=f.Starter(2,2);bad.OVR=70;bad.Potential=70;bad.Age=35;bad.InjuryWeeks=8;star.OVR=99;star.Potential=99;star.Age=23;Check(!f.EvaluateTrade(bad,star).Accepted&&!f.Trade(bad.Id,star.Id),"injured cheap veteran cannot buy a young star even with unlimited cash");int money=f.Credits;f.Round=8;Check(!f.Trade(get.Id,give.Id)&&f.Credits==money,"trade deadline rejection changes no ownership or money");
  int[] catches=new int[3];for(int grade=0;grade<3;grade++)for(int seed=0;seed<400;seed++){s=new Simulation(190000+seed);s.Practice=true;s.NewGame();s.Playbook=2;s.Snap();for(int n=0;n<30;n++)s.Update(.02f,0,0);s.BeginPass(0);s.Charge=.1f;s.ReleasePass();s.AggressiveCatch();s.CatchMeterValue=grade==0?.5f:grade==1?.65f:.05f;s.AggressiveCatch();for(int n=0;n<150&&s.State==Phase.Flight;n++)s.Update(.02f,0,0);if(s.Completions>0)catches[grade]++;}Console.WriteLine("Catch meter / 400 throws: green "+catches[0]+", yellow "+catches[1]+", red "+catches[2]);Check(catches[0]==400,"green timing guarantees catch");Check(catches[1]>=265&&catches[1]<=335,"yellow timing uses 75 percent success");Check(catches[2]>=5&&catches[2]<=30,"red timing uses 4 percent success");Check(Simulation.CatchChance(.5f)==1&&Simulation.CatchChance(.65f)==.75f&&Simulation.CatchChance(.05f)==.04f,"meter zones have exact specified probabilities");s=new Simulation(4);Check(!s.CatchMeterActive,"normal catching is default");Check(s.CallTimeout()&&s.CallTimeout()&&s.CallTimeout()&&!s.CallTimeout()&&s.Timeouts==0,"exactly three timeouts in first half");s.Quarter=2;s.Clock=0;typeof(Simulation).GetMethod("CheckQuarter",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(s,null);Check(s.Timeouts==3&&s.Quarter==3,"halftime restores three timeouts");s.BeginSecondHalf();s.Next();Check(s.Timeouts==3,"second-half possession does not spend a timeout");
 }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}Console.WriteLine("Playbook update: "+checks+" checks, "+failures+" failures");return failures;}
}
}
